import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"留白不是极简：有意味的空 vs 没东西","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/design/eastern-negative-space.md","filePath":"topics/design/eastern-negative-space.md"}'),g={name:"topics/design/eastern-negative-space.md"};function e(i,t,a,u,l,q){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="留白不是极简-有意味的空-vs-没东西" tabindex="-1">留白不是极简：有意味的空 vs 没东西 <a class="header-anchor" href="#留白不是极简-有意味的空-vs-没东西" aria-label="Permalink to &quot;留白不是极简：有意味的空 vs 没东西&quot;">​</a></h1><blockquote><p>来源：zh.wikipedia ⟪马远⟫、⟪夏圭⟫、⟪园冶⟫、⟪侘寂⟫；ja.wikipedia ⟪無印良品⟫、⟪借景⟫；en.wikipedia ⟪White (Kenya Hara book)⟫、⟪Muji⟫、⟪4′33″⟫；<strong>一手</strong>：東京国立博物館 ColBase 藏品说明（TA-140）、原研哉官网 ndc.co.jp；<strong>古籍原文</strong>：zh.wikisource ⟪畫筌⟫（笪重光）、⟪藝舟雙楫⟫卷五（包世臣）、⟪南宗抉秘⟫（华琳，负向核实） 链接：<a href="https://colbase.nich.go.jp/collection_items/tnm/TA-140" target="_blank" rel="noreferrer">https://colbase.nich.go.jp/collection_items/tnm/TA-140</a> ｜ <a href="https://zh.wikisource.org/wiki/%E7%95%AB%E7%AD%8C" target="_blank" rel="noreferrer">https://zh.wikisource.org/wiki/畫筌</a> ｜ <a href="https://zh.wikisource.org/wiki/%E8%97%9D%E8%88%9F%E9%9B%99%E6%A5%AB/%E5%8D%B7%E4%BA%94" target="_blank" rel="noreferrer">https://zh.wikisource.org/wiki/藝舟雙楫/卷五</a> 核实状态：✅ = 已核对原始/一手来源；⚠️ = 未取得一手确认，<strong>本文档不当事实使用</strong>（核实日期 2026-09-20）</p></blockquote><h2 id="一、先把两个词掰开" tabindex="-1">一、先把两个词掰开 <a class="header-anchor" href="#一、先把两个词掰开" aria-label="Permalink to &quot;一、先把两个词掰开&quot;">​</a></h2><p>主文档讲的是<strong>西方极简主义</strong>：成本最小、冒犯最小、地方性最小的三重合流。东方有一支看起来像它的东西——中国画的留白、日本的「間（ま）」、原研哉的&quot;白&quot;。它们<strong>外观相似，机制相反</strong>：</p><ul><li><strong>极简是减法</strong>：从已有的东西里拿掉，目标是剩下的更少更好；</li><li><strong>留白是经营</strong>：空的部分和实的地方一样要&quot;画&quot;，目标是<strong>让空的部分承担意义</strong>。</li></ul><p>一句话对比：<strong>极简省掉东西，留白安排空。</strong> 前者管理的是&quot;物&quot;，后者管理的是&quot;关系与呼吸&quot;。</p><h2 id="二、中国画的-空-不是没画完-是画不完" tabindex="-1">二、中国画的&quot;空&quot;：不是没画完，是画不完 <a class="header-anchor" href="#二、中国画的-空-不是没画完-是画不完" aria-label="Permalink to &quot;二、中国画的&quot;空&quot;：不是没画完，是画不完&quot;">​</a></h2><ul><li>南宋<strong>马远</strong>被称「<strong>马一角</strong>」、<strong>夏圭</strong>被称「<strong>夏半边</strong>」，二人合称「马一角、夏半边」✅；马远的画在当时被评作「<strong>边角之景</strong>」，与李唐、刘松年、夏圭合称<strong>南宋四家</strong> ✅</li><li>关键不在&quot;画得少&quot;，而在<strong>取景方式</strong>：把全景收进一角，剩下的空白不是遗漏，而是<strong>让观者站到画面里去补全的那个位置</strong>。这不是省略信息，是<strong>转移了工作</strong>——从作者转移给观者。</li><li>这也解释了为什么它和&quot;极简&quot;不是一回事：极简把工作转移给了<strong>成本表</strong>（省料省工序），留白把工作转移给了<strong>观者</strong>（用想象补全）。<strong>接收者不同，意义就完全不同。</strong></li></ul><h2 id="三、引文考古-谁真的说了什么-本节是方法论-也是纠错" tabindex="-1">三、引文考古：谁真的说了什么（本节是方法论，也是纠错） <a class="header-anchor" href="#三、引文考古-谁真的说了什么-本节是方法论-也是纠错" aria-label="Permalink to &quot;三、引文考古：谁真的说了什么（本节是方法论，也是纠错）&quot;">​</a></h2><p>中文世界关于留白的引文长期互相转抄，本轮做了逐条<strong>全文检索式核实</strong>，结果并不整齐：</p><table tabindex="0"><thead><tr><th>说法</th><th>核实结果</th><th>状态</th></tr></thead><tbody><tr><td>「虚实相生，无画处皆成妙境」</td><td><strong>确实见于笪重光《画筌》原文</strong></td><td>✅</td></tr><tr><td>「计白当黑」</td><td><strong>确实见于包世臣《艺舟双楫》卷五</strong>（论邓石如书法的章法）</td><td>✅</td></tr><tr><td>华琳《南宗抉秘》论留白</td><td><strong>全文检索无「无画处」「空白」「计白」「妙境」等字样 → 应判为误归</strong></td><td>❌ 已证伪</td></tr><tr><td>宗白华《美学散步》论空白</td><td>中英文来源均未取得可引原文；相关网络引文无法溯源</td><td>⚠️ <strong>不写入</strong></td></tr><tr><td>「这样就好」（これでいい）作为 MUJI 口号</td><td>维基条目中查无此表述；MUJI 早期可见的原话是「わけあって、安い。」</td><td>⚠️ <strong>不写入</strong></td></tr></tbody></table><p><strong>这一节的意义大于结论</strong>：「计白当黑」这四个字之所以好引用，正是因为它听起来像一句可以直接用的设计箴言——<strong>而它其实出自讨论书法章法的语境</strong>（邓石如的篆刻与书法）。把它剥离语境搬到排版、UI、产品设计上，就是本库在别处反复记过的那种失真：<strong>句子是真的，语境被换掉了。</strong></p><p>另外注意《南宗抉秘》那条：<strong>误归可以靠全文检索直接证伪</strong>，不需要依赖二手文章的权威感。这是可复用的方法——<strong>引一句古话之前，先搜原文</strong>。（附带一条工程提示：ctext.org 明确反爬，且声明会向爬虫故意返回损坏数据；古籍原文优先用 wikisource 类可核对文本。）</p><h2 id="四、最锋利的一刀-《寒江独钓图》自己拆穿了-留白叙事" tabindex="-1">四、最锋利的一刀：《寒江独钓图》自己拆穿了&quot;留白叙事&quot; <a class="header-anchor" href="#四、最锋利的一刀-《寒江独钓图》自己拆穿了-留白叙事" aria-label="Permalink to &quot;四、最锋利的一刀：《寒江独钓图》自己拆穿了&quot;留白叙事&quot;&quot;">​</a></h2><p>这是本轮最有价值的发现，也直接改写了&quot;留白&quot;的教科书叙事：</p><ul><li>传为马远的《<strong>寒江独钓图</strong>》，藏<strong>東京国立博物館</strong>：馆方登记为「<strong>伝馬遠筆</strong>」（传马远笔，<strong>非确证真迹</strong>），列为<strong>重要文化財</strong>，定为南宋时代·13 世纪，绢本墨画淡彩，本纸 <strong>26.7 × 50.6 cm</strong>，管理番号 TA-140，英译 <em>Solitary Angler on a Wintry River</em> ✅</li><li>同一份馆方说明还写着：该图<strong>自古因留白（余白）营造的诗意氛围而受到评价，但现在被推测原是一件更大画面的作品被巧妙裁剪（trimming）而成</strong> ✅</li></ul><p>两句话合起来把问题翻转了：<strong>我们当作&quot;留白典范&quot;的那张图，可能是一片被后世框选出来的空白。</strong> 也就是说——</p><ul><li>「作者当年经营出的空」与「后人从画面里裁出来的空」，<strong>在同一张图上可能无法区分</strong>；</li><li>一件作品被封为极简/留白的典型，往往发生在它<strong>被从原语境中切出来、放进美术馆的墙和白纸之间的那一刻</strong>。</li><li>这和主文档里那层张力用的是同一个逻辑：<strong>极简的&quot;必然性&quot;部分是被叙述出来的，而不是被证明的。</strong> 留白这边的对应物就是：<strong>&quot;有意味的空&quot;可能是被框出来的，不是被画出来的。</strong></li></ul><p>（所以本文档给出一条自律：凡引用&quot;留白典范&quot;，先问它<strong>是否为传本、是否被裁剪、原始语境是什么</strong>。）</p><h2 id="五、园林-把墙外的空也经营进来" tabindex="-1">五、园林：把墙外的空也经营进来 <a class="header-anchor" href="#五、园林-把墙外的空也经营进来" aria-label="Permalink to &quot;五、园林：把墙外的空也经营进来&quot;">​</a></h2><p>留白不止发生在纸面。中国园林的成熟文献给出了&quot;空&quot;的另一种经营方式：</p><ul><li>明代<strong>计成</strong>《<strong>园冶</strong>》：<strong>崇祯四年（1631）成书、崇祯七年（1634）刻印</strong>，传入日本后被称「<strong>夺天工</strong>」✅；主导思想包括「<strong>造园无格，必须巧于因借，精在体宜</strong>」「<strong>虽由人作，宛自天开</strong>」「<strong>三分匠、七分主人</strong>」，目录中设有「<strong>借景</strong>」专章 ✅</li><li><strong>借景四分类</strong> ✅：遠借（远山湖景）、隣借（邻近建筑）、仰借（云、星）、俯借（岩石、池水）——原书末章即为「借景」</li></ul><p><strong>&quot;借&quot;这件事的机制与留白完全同构</strong>：不新增物，而是<strong>把园外的既有之物纳入构图</strong>。差别在于留白&quot;借&quot;的是观者的想象，借景&quot;借&quot;的是别人已经建好的东西——山、塔、云、寺钟声。</p><p>对照起来看极简就更清楚了：极简的空间里，<strong>没有东西被请进来</strong>（只有被拿走的东西），而留白/借景的空间里，<strong>始终有东西在被安排</strong>。前者的空虚是结果，后者的空虚是结构。</p><h2 id="六、日本这一支-侘寂、-間-与待填的空" tabindex="-1">六、日本这一支：侘寂、&quot;間&quot;与待填的空 <a class="header-anchor" href="#六、日本这一支-侘寂、-間-与待填的空" aria-label="Permalink to &quot;六、日本这一支：侘寂、&quot;間&quot;与待填的空&quot;">​</a></h2><ul><li><strong>侘寂（侘び寂び）<strong>以</strong>接受短暂与不完美</strong>为核心，常被概为三个事实：<strong>无可长存、无已完成、无完美</strong> ✅；铃木大拙将「侘」释为<strong>简朴、非时尚</strong> ✅；《阴翳礼赞》通常被视为对侘寂的一种诠释 ✅（<strong>成书年份本轮未核实</strong> ⚠️）</li><li><strong>原研哉</strong>对&quot;白&quot;的定义是这条线里最清楚的一段自述。他在《<strong>白</strong>》（<em>White</em>，Lars Müller，2010）里写道 ✅：白意味着「<strong>emptiness</strong>」（空），而空<strong>不是</strong>「nothingness」（无）、也不是&quot;没有能量&quot;；空是一种<strong>状态</strong>，一种 <em>kizen</em>（機前/期然），<strong>&quot;在将来很可能被内容填满&quot;</strong>，因而能**&quot;产生一种强有力的沟通能量&quot;**。</li><li>履历事实 ✅：原研哉 <strong>1958 年生</strong>；<strong>2001 年</strong>由<strong>田中一光</strong>任命为 <strong>MUJI 艺术总监</strong>；MUJI 的初始概念由田中一光与小池一子、杉本貴志共同发展，<strong>田中一光是第一位艺术总监</strong>。</li><li>著作版本 ✅：《设计中的设计》日文原版《デザインのデザイン》（<strong>岩波書店，2003-12-25</strong>），英文版 <em>Designing Design</em>（Lars Müller，2007）。</li></ul><p><strong>关键区分就在那句 &quot;will likely be filled with content in the future&quot;</strong>：原研哉的空是<strong>待填的空</strong>（一个容器，因为空而能容纳多样性与未来），西方极简的空是<strong>取消后的余量</strong>（一个结果，因为拿掉了而有&quot;现代感&quot;）。<strong>前者是把它留出来，后者是把它省下来。</strong></p><h3 id="一个必须写的分层-muji-不是一直-空" tabindex="-1">一个必须写的分层：MUJI 不是一直&quot;空&quot; <a class="header-anchor" href="#一个必须写的分层-muji-不是一直-空" aria-label="Permalink to &quot;一个必须写的分层：MUJI 不是一直&quot;空&quot;&quot;">​</a></h3><ul><li>MUJI <strong>1980 年</strong>创立（西友的 PB 品牌，最初 <strong>40 个品目</strong>）✅；<strong>早期的营销概念是「わけあり商品」——&quot;有原因（所以才便宜）的商品&quot;，宣传语是「わけあって、安い。」</strong> ✅</li><li>也就是说：<strong>1980 年代的 MUJI 讲的是成本叙事</strong>（有瑕疵/简化规格，所以便宜），<strong>2001 年原研哉接手后的 MUJI 才讲意义叙事</strong>（空容器、白、这样就好 ⚠️）。</li></ul><p><strong>把 MUJI 的&quot;空&quot;直接当成&quot;东方极简主义&quot;、再和西方极简等同，是把两个阶段的 MUJI 混为一谈。</strong> 更精确的表述是：<strong>MUJI 早年的&quot;省略&quot;和后来被赋予的&quot;空&quot;，是先后叠加的两层叙事</strong>——一层关于价格，一层关于哲学；而<strong>商业上它们完全可以被同一批消费者读成同一件事</strong>。这正是本库反复出现的那个结构：<strong>同一外观，不同动机，靠外观分辨不出来。</strong></p><h2 id="七、西方从东方借-空-4′33′′及其未核实的师承" tabindex="-1">七、西方从东方借&quot;空&quot;：4′33″及其未核实的师承 <a class="header-anchor" href="#七、西方从东方借-空-4′33′′及其未核实的师承" aria-label="Permalink to &quot;七、西方从东方借&quot;空&quot;：4′33″及其未核实的师承&quot;">​</a></h2><ul><li><strong>John Cage《4′33″》创作于 1952 年</strong> ✅——四个多钟头里演奏者不奏一个音，让环境声成为音乐。这是西方艺术史上最纯粹的&quot;留白&quot;操作：<strong>把空安排成作品本身</strong>，并把工作交给听众。</li><li>常听到的说法是 Cage 深受铃木大拙影响（1940–50 年代在哥伦比亚大学听其讲课）。<strong>本轮未能证实这一师承关系 ⚠️</strong>：en.wikipedia 的 Cage 词条全文仅出现一次 Suzuki，铃木大拙词条中虽出现 Columbia 三处，但<strong>没有 Cage 字样</strong>。学界的处理方式通常是引 Kay Larson《Where the Heart Beats》或 Cage 自述，本轮不可达。</li><li>所以本文档只写：<strong>4′33″ 的时间与形式事实成立 ✅；&quot;受铃木大拙直接影响&quot;作为流传说法标为 ⚠️</strong>。这类&quot;东西方互相验证&quot;的叙事最容易长出神话，本库的纪律是<strong>宁可留一个空格，也不填一个假答案</strong>。</li></ul><h2 id="八、对照表-留白-vs-极简" tabindex="-1">八、对照表：留白 vs 极简 <a class="header-anchor" href="#八、对照表-留白-vs-极简" aria-label="Permalink to &quot;八、对照表：留白 vs 极简&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>留白 / 間 / 白</th><th>极简主义</th></tr></thead><tbody><tr><td>意图</td><td><strong>有意味的空</strong>：空是有内容的</td><td><strong>取消多余的物</strong>：空是结果</td></tr><tr><td>机制</td><td>经营关系：虚实相生、借景、待填的容器</td><td>收敛变量：成本、冒犯、去地方性</td></tr><tr><td>工作交给谁</td><td><strong>观者</strong>（想象补全）/ 使用者（填进未来）</td><td><strong>成本表与供应链</strong>（省料、省工序、省风险）</td></tr><tr><td>时间性</td><td>空<strong>随时间变化</strong>（四季、光线、使用、被填满）</td><td>冻结为一张图、一套规范</td></tr><tr><td>失败形态</td><td>空得没有可补全的结构 → 观者不知道该怎么办</td><td>省掉了能力 → 可用性下降（Nielsen 2017 扁平界面慢 22%，见主文档）</td></tr><tr><td>商业变体</td><td>MUJI 2001 后的&quot;空容器&quot;</td><td>品牌趋同、扁平化界面、敌意建筑</td></tr></tbody></table><blockquote><p>表格里最可操作的一行是&quot;失败形态&quot;：<strong>留白失败是因为空里没有线索，极简失败是因为少里没有能力。</strong></p></blockquote><h2 id="九、判据-怎么分辨-经营的空-与-省出来的空" tabindex="-1">九、判据：怎么分辨&quot;经营的空&quot;与&quot;省出来的空&quot; <a class="header-anchor" href="#九、判据-怎么分辨-经营的空-与-省出来的空" aria-label="Permalink to &quot;九、判据：怎么分辨&quot;经营的空&quot;与&quot;省出来的空&quot;&quot;">​</a></h2><p>用于看设计（页面、海报、店面、发布会），四问：</p><ol><li><strong>空里有没有线索？</strong> 留白会留下引导（一条边、一段轴线、一个视线落点）；省出来的空<strong>什么都不留</strong>，只剩没被用满。</li><li><strong>谁在补全？</strong> 需要观者参与才算完成的，是留白；要求观者<strong>什么都不必做</strong>就接受的，是极简——<strong>后者不需要你</strong>。</li><li><strong>它连着外面吗？</strong> 借景式的空<strong>指向墙外的具体之物</strong>（真山、真塔）；极简式的空<strong>指向自己</strong>（规范、系统、模板）。</li><li><strong>它是&quot;待填&quot;还是&quot;已空&quot;？</strong> 原研哉的判准：空要能&quot;在将来被内容填满&quot;。一个能被填进不同内容的容器是留白；一个<strong>填什么都显得多余</strong>的表面是极简。</li></ol><h2 id="十、一句话" tabindex="-1">十、一句话 <a class="header-anchor" href="#十、一句话" aria-label="Permalink to &quot;十、一句话&quot;">​</a></h2><p><strong>极简是&quot;把东西拿掉&quot;，留白是&quot;把东西留出来&quot;；一个问的是还能少什么，一个问的是空处要发生什么。</strong> 而当《寒江独钓图》被证明很可能是从大画面上裁下来的一角时，我们也得到一个更普遍的提醒：<strong>&quot;有意味的空&quot;也可能被后人框出来——判断它，要看那些线索是不是原本就长在那里。</strong></p><hr><blockquote><p>关键词：极简主义、留白、东方美学、马远、夏圭、寒江独钓图、画筌、计白当黑、艺舟双楫、园冶、借景、侘寂、原研哉、无印良品、白、4′33″、引文考古、且慢核实 关联：</p><ul><li><code>topics/design/minimalism-death-of-detail.md</code>：本文档是主文档的东方对照面——同一种&quot;少&quot;，两种相反的机制（省出来 vs 经营出来）</li><li><code>topics/design/less-but-better-engineering.md</code>：第九节的&quot;谁在补全&quot;与工程判据&quot;复杂度推给了谁&quot;是同一个问题的两个场合</li><li><code>topics/weiqi/</code>：围棋的&quot;气&quot;是这套美学最硬的实例——<strong>空点不是没落子，而是棋子活着的条件</strong>；提子之后留下的空更是&quot;经营出来的空&quot;</li><li><code>topics/philosophy/</code>：侘寂&quot;三个否定&quot;（无可长存、无已完成、无完美）与禅学对&quot;完成&quot;的态度，是留白美学的观念底座</li><li><code>topics/culture/</code>：MUJI 从「わけあって、安い」到&quot;空容器&quot;的叙事重心转移，是品牌如何给&quot;省略&quot;补上一层意义的标准案例</li><li><code>topics/design/logo-convergence.md</code>：极简的&quot;空&quot;在商业上会被读成中性，留白的&quot;空&quot;会被读成意境——外观相近、机制相反，正是本文与那篇的接口</li></ul></blockquote><blockquote><p>整理日期：2026-09-20</p></blockquote>',43)])])}const c=o(g,[["render",e]]);export{h as __pageData,c as default};
